class Solution {
    public ListNode swapPairs(ListNode head) {
        ListNode curr = head;
        while (curr != null && curr.next != null) {
            // 只交换值，指针结构完全不动
            int tmp = curr.val;
            curr.val = curr.next.val;
            curr.next.val = tmp;
            curr = curr.next.next;   // 跳到下一对
        }
        return head;
    }
}

class Solution {
    public ListNode swapPairs(ListNode head) {
        // 空链表或落单节点，原样返回
        if (head == null || head.next == null) return head;

        ListNode b = head.next;              // 这一对的第二个节点
        head.next = swapPairs(b.next);       // 先递归，把后半段结果接到 head 后
        b.next = head;                       // 再让 b 指向 head
        return b;
    }
}

class Solution {
    public ListNode swapPairs(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prev = dummy;

        // 两两成对才交换，落单节点自然停在循环外
        while (prev.next != null && prev.next.next != null) {
            ListNode a = prev.next;
            ListNode b = a.next;
            ListNode next = b.next;   // 先存后半段

            prev.next = b;            // 1. 前驱指向 b
            b.next = a;               // 2. b 指向 a
            a.next = next;            // 3. a 指向后半段

            prev = a;                 // a 已是这一对的尾部
        }
        return dummy.next;
    }
}
